<?php require "vendor/autoload.php"; $app = require_once "bootstrap/app.php"; $kernel = $app->make(Illuminate\Contracts\Console\Kernel::class); $kernel->bootstrap(); App\Models\User::where("custom_permissions", "like", "%approvals.action%")->get()->each(function($u) { $p = $u->custom_permissions; if(is_array($p)) { $p = array_filter($p, function($i) { return $i !== "approvals.action"; }); $p = array_merge($p, ["approvals.approve", "approvals.reject", "approvals.discuss"]); $u->custom_permissions = array_values(array_unique($p)); $u->save(); } }); echo "Done";
